#include <bits/stdc++.h>
using namespace std;

void solve()
{
    int n; cin >> n;
    vector<int> arr(n);
    for(int i=0;i<n;i++){
        cin >> arr[i];
        
    }
    int ans = 0, ind = -1;
    for(int i=0;i<n-1;i++){
        if (abs(arr[i] - arr[i+1]) >= ans){
            ans = abs(arr[i] - arr[i + 1]);
            ind = i;
        }
    }
    
    
    // ans = max(ans , abs(arr[0]-arr[n-1]));
    vector<int> shf = vector<int> (arr.begin() + ind + 1, arr.end());
    for (int j = 0; j <= ind; j++) shf.push_back(arr[j]);
    int ans2 = 0;
    for (int i = 0; i < n - 1; i++){
        if (abs(shf[i] - shf[i + 1]) >= ans2){
            ans2 = abs(shf[i] - shf[i + 1]);
        }
    }
    cout << min(ans, ans2) << endl;
    
